"""Entity-type inheritance: `is_abstract` and `inherited_from` (queue R18).

A type may inherit from another type of its domain (`truck` from `vehicle`):
it has its ancestors' attributes as well as its own, a relationship or a
parameter over an ancestor takes its entities, and a model's set over a type
ranges over its own entities and every descendant's. An abstract type holds
no entities of its own -- only its descendants do. Held here, in the
database, as every other rule about the domain's data is:

- `entity_type_lineage` (a type and its ancestors), `entity_type_family` (a
  type and its descendants) and `entity_type_is_a`;
- no cycles, and one meaning per attribute name along a lineage;
- `entity_validate`: attributes and defaults from the whole lineage, and no
  entity of an abstract type; `relationship_validate` and
  `parameter_value_validate`: an entity of a descendant type fits;
- `snapshot_dataset`: a set is its type's family; a parameter's cells are
  keyed by the parameter's own index types.

A domain with no inheritance snapshots exactly as before, so dataset hashes
stay put. The downgrade restores the four functions as 0065 left them.
"""

from alembic import op

revision = "0066"
down_revision = "0065"
branch_labels = None
depends_on = None

_HELPERS = '\n        CREATE OR REPLACE FUNCTION entity_type_lineage(p_type bigint) RETURNS bigint[]\n        LANGUAGE sql STABLE AS $$\n            -- The type and every type it inherits from, nearest first.\n            WITH RECURSIVE up(id, depth) AS (\n                SELECT p_type, 0\n                UNION ALL\n                SELECT t.inherited_from, up.depth + 1 FROM entity_type t JOIN up ON t.id = up.id\n                 WHERE t.inherited_from IS NOT NULL AND up.depth < 64)\n            SELECT coalesce(array_agg(id ORDER BY depth), ARRAY[p_type]) FROM up;\n        $$;\n\n        CREATE OR REPLACE FUNCTION entity_type_family(p_type bigint) RETURNS bigint[]\n        LANGUAGE sql STABLE AS $$\n            -- The type and every type that inherits from it, however deep.\n            WITH RECURSIVE down(id, depth) AS (\n                SELECT p_type, 0\n                UNION ALL\n                SELECT t.id, down.depth + 1 FROM entity_type t JOIN down ON t.inherited_from = down.id\n                 WHERE down.depth < 64)\n            SELECT coalesce(array_agg(id), ARRAY[p_type]) FROM down;\n        $$;\n\n        CREATE OR REPLACE FUNCTION entity_type_is_a(p_type bigint, p_ancestor bigint) RETURNS boolean\n        LANGUAGE sql STABLE AS $$\n            SELECT p_ancestor = ANY (entity_type_lineage(p_type));\n        $$;\n\n        CREATE OR REPLACE FUNCTION entity_type_inherit_validate() RETURNS trigger LANGUAGE plpgsql AS $$\n        DECLARE v_clash text;\n        BEGIN\n            IF NEW.inherited_from IS NOT NULL THEN\n                IF NEW.inherited_from = NEW.id OR NEW.id = ANY (entity_type_lineage(NEW.inherited_from)) THEN\n                    RAISE EXCEPTION \'entity type "%" cannot inherit from one of its own descendants\', NEW.name\n                        USING ERRCODE = \'23514\',\n                              DETAIL  = jsonb_build_object(\'kind\', \'inheritance_cycle\', \'field\', \'inherited_from\',\n                                                           \'record\', NEW.name)::text;\n                END IF;\n                -- One name, one meaning along a lineage: an attribute of the new ancestors may not be\n                -- declared again anywhere in this type\'s family.\n                SELECT a.name INTO v_clash FROM attribute_def a\n                 WHERE a.entity_type_id = ANY (entity_type_lineage(NEW.inherited_from))\n                   AND EXISTS (SELECT 1 FROM attribute_def b\n                                WHERE b.entity_type_id = ANY (entity_type_family(NEW.id)) AND b.name = a.name)\n                 LIMIT 1;\n                IF v_clash IS NOT NULL THEN\n                    RAISE EXCEPTION \'entity type "%" already has an attribute "%" that its new ancestors declare\', NEW.name, v_clash\n                        USING ERRCODE = \'23514\',\n                              DETAIL  = jsonb_build_object(\'kind\', \'inherited_attribute_clash\', \'field\', \'inherited_from\',\n                                                           \'record\', v_clash)::text;\n                END IF;\n            END IF;\n            IF NEW.is_abstract AND (TG_OP = \'INSERT\' OR NOT OLD.is_abstract)\n               AND EXISTS (SELECT 1 FROM entity WHERE entity_type_id = NEW.id) THEN\n                RAISE EXCEPTION \'entity type "%" has entities of its own, so it cannot be abstract\', NEW.name\n                    USING ERRCODE = \'23514\',\n                          DETAIL  = jsonb_build_object(\'kind\', \'abstract_has_entities\', \'field\', \'is_abstract\',\n                                                       \'record\', NEW.name)::text;\n            END IF;\n            RETURN NEW;\n        END $$;\n\n        CREATE OR REPLACE FUNCTION attribute_def_inherit_validate() RETURNS trigger LANGUAGE plpgsql AS $$\n        BEGIN\n            -- An attribute\'s name is its lineage\'s: not declared by an ancestor, nor by a descendant.\n            IF EXISTS (SELECT 1 FROM attribute_def a\n                        WHERE a.name = NEW.name AND a.id IS DISTINCT FROM NEW.id\n                          AND a.entity_type_id <> NEW.entity_type_id\n                          AND (a.entity_type_id = ANY (entity_type_lineage(NEW.entity_type_id))\n                               OR a.entity_type_id = ANY (entity_type_family(NEW.entity_type_id)))) THEN\n                RAISE EXCEPTION \'attribute "%" is already declared along this type\'\'s inheritance\', NEW.name\n                    USING ERRCODE = \'23514\',\n                          DETAIL  = jsonb_build_object(\'kind\', \'inherited_attribute_clash\', \'field\', \'name\',\n                                                       \'record\', NEW.name)::text;\n            END IF;\n            RETURN NEW;\n        END $$;\n'

_ENTITY_VALIDATE = 'CREATE OR REPLACE FUNCTION public.entity_validate()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n    DECLARE d attribute_def; v jsonb; k text;\n    BEGIN\n        IF (SELECT is_abstract FROM entity_type WHERE id = NEW.entity_type_id) THEN\n            RAISE EXCEPTION \'entity %: its type is abstract and holds no entities of its own; use one of the types that inherit from it\', NEW.key\n                USING ERRCODE = \'23514\',\n                      DETAIL  = jsonb_build_object(\'kind\', \'abstract_type\', \'field\', \'entity_type_id\', \'record\', NEW.key)::text;\n        END IF;\n        FOR k IN SELECT jsonb_object_keys(NEW.attrs) LOOP\n            IF NOT EXISTS (SELECT 1 FROM attribute_def\n                           WHERE entity_type_id = ANY (entity_type_lineage(NEW.entity_type_id)) AND name = k) THEN\n                RAISE EXCEPTION \'entity %: unknown attribute "%"\', NEW.key, k\n                    USING ERRCODE = \'23514\',\n                          DETAIL  = jsonb_build_object(\'kind\', \'unknown_attribute\', \'field\', k, \'record\', NEW.key)::text;\n            END IF;\n        END LOOP;\n        FOR d IN SELECT * FROM attribute_def WHERE entity_type_id = ANY (entity_type_lineage(NEW.entity_type_id)) LOOP\n            v := NEW.attrs -> d.name;\n            IF v IS NULL AND d.default_value IS NOT NULL THEN\n                NEW.attrs := NEW.attrs || jsonb_build_object(d.name, d.default_value);\n                v := d.default_value;\n            END IF;\n            IF v IS NULL OR v = \'null\' THEN\n                IF d.required THEN\n                    RAISE EXCEPTION \'entity %: attribute "%" is required\', NEW.key, d.name\n                        USING ERRCODE = \'23514\',\n                              DETAIL  = jsonb_build_object(\'kind\', \'required_attribute\', \'field\', d.name, \'record\', NEW.key)::text;\n                END IF;\n                CONTINUE;\n            END IF;\n            IF NOT attr_value_matches_type(d.data_type, d.enum_values, v) THEN\n                RAISE EXCEPTION \'entity %: attribute "%" must be %\', NEW.key, d.name, d.data_type\n                    USING ERRCODE = \'23514\',\n                          DETAIL  = jsonb_build_object(\'kind\', \'attribute_type\', \'field\', d.name,\n                                                       \'record\', NEW.key, \'expected\', d.data_type::text)::text;\n            END IF;\n        END LOOP;\n        RETURN NEW;\n    END $function$'
_RELATIONSHIP_VALIDATE = 'CREATE OR REPLACE FUNCTION public.relationship_validate()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE rt relationship_type;\n        BEGIN\n            SELECT * INTO rt FROM relationship_type WHERE id = NEW.relationship_type_id;\n            IF NOT entity_type_is_a((SELECT entity_type_id FROM entity WHERE id = NEW.from_entity_id), rt.from_type_id)\n            OR NOT entity_type_is_a((SELECT entity_type_id FROM entity WHERE id = NEW.to_entity_id), rt.to_type_id) THEN\n                RAISE EXCEPTION \'relationship "%": entity types do not match\', rt.name\n                    USING ERRCODE = \'23514\',\n                          DETAIL  = jsonb_build_object(\n                              \'kind\',           \'type_mismatch\',\n                              \'field\',          rt.name,\n                              \'from_entity_id\', NEW.from_entity_id,\n                              \'to_entity_id\',   NEW.to_entity_id)::text;\n            END IF;\n            IF rt.cardinality IN (\'one_to_many\', \'one_to_one\') AND EXISTS (\n                SELECT 1 FROM relationship r WHERE r.relationship_type_id = rt.id\n                   AND r.to_entity_id = NEW.to_entity_id AND r.id IS DISTINCT FROM NEW.id) THEN\n                RAISE EXCEPTION \'relationship "%": target already has a source\', rt.name\n                    USING ERRCODE = \'23514\',\n                          DETAIL  = jsonb_build_object(\n                              \'kind\',           \'cardinality\',\n                              \'field\',          rt.name,\n                              \'cardinality\',    rt.cardinality,\n                              \'to_entity_id\',   NEW.to_entity_id)::text;\n            END IF;\n            IF rt.cardinality IN (\'many_to_one\', \'one_to_one\') AND EXISTS (\n                SELECT 1 FROM relationship r WHERE r.relationship_type_id = rt.id\n                   AND r.from_entity_id = NEW.from_entity_id AND r.id IS DISTINCT FROM NEW.id) THEN\n                RAISE EXCEPTION \'relationship "%": source already has a target\', rt.name\n                    USING ERRCODE = \'23514\',\n                          DETAIL  = jsonb_build_object(\n                              \'kind\',           \'cardinality\',\n                              \'field\',          rt.name,\n                              \'cardinality\',    rt.cardinality,\n                              \'from_entity_id\', NEW.from_entity_id)::text;\n            END IF;\n            IF rt.is_hierarchy AND (NEW.from_entity_id = NEW.to_entity_id OR EXISTS (\n                WITH RECURSIVE down AS (\n                    SELECT to_entity_id AS id FROM relationship\n                     WHERE relationship_type_id = rt.id\n                       AND from_entity_id = NEW.to_entity_id\n                       AND id IS DISTINCT FROM NEW.id\n                    UNION\n                    SELECT r.to_entity_id FROM relationship r JOIN down ON r.from_entity_id = down.id\n                     WHERE r.relationship_type_id = rt.id\n                       AND r.id IS DISTINCT FROM NEW.id)\n                SELECT 1 FROM down WHERE id = NEW.from_entity_id)) THEN\n                RAISE EXCEPTION \'relationship "%": would create a cycle\', rt.name\n                    USING ERRCODE = \'23514\',\n                          DETAIL  = jsonb_build_object(\n                              \'kind\',           \'cycle\',\n                              \'field\',          rt.name,\n                              \'from_entity_id\', NEW.from_entity_id,\n                              \'to_entity_id\',   NEW.to_entity_id)::text;\n            END IF;\n            RETURN NEW;\n        END $function$'
_PARAMETER_VALUE_VALIDATE = "CREATE OR REPLACE FUNCTION public.parameter_value_validate()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE want bigint[]; got bigint[];\n        BEGIN\n            SELECT index_type_ids INTO want FROM parameter_def WHERE id = NEW.parameter_def_id;\n            SELECT array_agg(e.entity_type_id ORDER BY u.ord) INTO got\n              FROM unnest(NEW.entity_ids) WITH ORDINALITY u(id, ord) JOIN entity e ON e.id = u.id;\n            IF cardinality(got) IS DISTINCT FROM cardinality(want) OR EXISTS (\n                SELECT 1 FROM generate_subscripts(want, 1) AS i WHERE NOT entity_type_is_a(got[i], want[i])) THEN\n                RAISE EXCEPTION\n                    'parameter_value: index % does not match parameter index types', NEW.entity_ids\n                    USING ERRCODE = '23514',\n                          DETAIL  = jsonb_build_object(\n                              'kind',     'parameter_index',\n                              'field',    'entity_ids',\n                              'record',   NEW.entity_ids,\n                              'expected', want)::text;\n            END IF;\n            RETURN NEW;\n        END $function$"
_SNAPSHOT_DATASET = 'CREATE OR REPLACE FUNCTION public.snapshot_dataset(p_model_version bigint)\n RETURNS bigint\n LANGUAGE plpgsql\nAS $function$\n        DECLARE\n            v_problem bigint; v_domain bigint; v_ir jsonb;\n            v_sets jsonb := \'{}\'; v_params jsonb := \'{}\'; v_labels jsonb := \'{}\';\n            v_defaults jsonb := \'{}\';\n            v_rels jsonb := \'{}\';\n            v_name text; v_rows jsonb; v_data jsonb; v_id bigint; v_hash text;\n        BEGIN\n            SELECT mv.problem_id, p.domain_id, mv.ir INTO v_problem, v_domain, v_ir\n              FROM model_version mv JOIN problem p ON p.id = mv.problem_id\n             WHERE mv.id = p_model_version;\n            IF NOT FOUND THEN\n                RAISE EXCEPTION \'model_version % not found\', p_model_version;\n            END IF;\n\n            FOR v_name IN SELECT jsonb_array_elements_text(v_ir -> \'sets\') LOOP\n                IF NOT EXISTS (SELECT 1 FROM entity_type\n                               WHERE domain_id = v_domain AND name = v_name) THEN\n                    RAISE EXCEPTION \'IR set "%" has no entity_type in this domain\', v_name;\n                END IF;\n                SELECT coalesce(jsonb_agg(jsonb_build_object(\'id\', e.key) || e.attrs\n                                          ORDER BY e.sort_order, e.key), \'[]\')\n                  INTO v_rows\n                  FROM entity e JOIN entity_type t ON t.id = e.entity_type_id\n                 WHERE t.domain_id = v_domain AND e.active\n                   AND t.id = ANY (entity_type_family((SELECT id FROM entity_type WHERE domain_id = v_domain AND name = v_name)));\n                v_sets := v_sets || jsonb_build_object(v_name, v_rows);\n                SELECT coalesce(jsonb_object_agg(e.key, e.label), \'{}\')\n                  INTO v_rows\n                  FROM entity e JOIN entity_type t ON t.id = e.entity_type_id\n                 WHERE t.domain_id = v_domain AND e.active AND e.label IS NOT NULL\n                   AND t.id = ANY (entity_type_family((SELECT id FROM entity_type WHERE domain_id = v_domain AND name = v_name)));\n                v_labels := v_labels || jsonb_build_object(v_name, v_rows);\n            END LOOP;\n\n            FOR v_name IN SELECT jsonb_object_keys(coalesce(v_ir -> \'parameters\', \'{}\')) LOOP\n                IF NOT EXISTS (SELECT 1 FROM parameter_def\n                               WHERE domain_id = v_domain AND name = v_name) THEN\n                    RAISE EXCEPTION \'IR parameter "%" has no parameter_def in this domain\', v_name;\n                END IF;\n                SELECT coalesce(jsonb_agg(row_json ORDER BY row_json::text), \'[]\')\n                  INTO v_rows FROM (\n                    SELECT CASE\n                             WHEN bigint_array_is_distinct(pd.index_type_ids)\n                             THEN jsonb_object_agg(t.name, e.key)\n                             ELSE jsonb_object_agg((u.ord - 1)::text, e.key)\n                           END\n                           || jsonb_build_object(\'value\', trim_scale(pv.value))\n                              AS row_json\n                      FROM parameter_def pd\n                      JOIN parameter_value pv ON pv.parameter_def_id = pd.id\n                      CROSS JOIN LATERAL unnest(pv.entity_ids) WITH ORDINALITY AS u(eid, ord)\n                      JOIN entity e ON e.id = u.eid\n                      JOIN entity_type t ON t.id = pd.index_type_ids[u.ord]\n                     WHERE pd.domain_id = v_domain AND pd.name = v_name\n                     GROUP BY pv.parameter_def_id, pv.entity_ids, pv.value, pd.index_type_ids\n                    HAVING bool_and(e.active)) q;\n                v_params := v_params || jsonb_build_object(v_name, v_rows);\n                v_defaults := v_defaults || jsonb_build_object(v_name, (\n                    SELECT trim_scale(pd.default_value) FROM parameter_def pd\n                     WHERE pd.domain_id = v_domain AND pd.name = v_name));\n            END LOOP;\n\n            FOR v_name IN SELECT jsonb_array_elements_text(\n                                     coalesce(v_ir -> \'relationships\', \'[]\'::jsonb)) LOOP\n                IF NOT EXISTS (SELECT 1 FROM relationship_type\n                               WHERE domain_id = v_domain AND name = v_name) THEN\n                    RAISE EXCEPTION \'IR relationship "%" has no relationship_type in this domain\',\n                          v_name;\n                END IF;\n                SELECT coalesce(jsonb_agg(row_json ORDER BY row_json::text), \'[]\')\n                  INTO v_rows FROM (\n                    SELECT jsonb_build_object(\'from\', ef.key, \'to\', et.key)\n                           || CASE WHEN r.valid_from IS NULL THEN \'{}\'::jsonb\n                                   ELSE jsonb_build_object(\'valid_from\', r.valid_from) END\n                           || CASE WHEN r.valid_to IS NULL THEN \'{}\'::jsonb\n                                   ELSE jsonb_build_object(\'valid_to\', r.valid_to) END\n                           || CASE WHEN r.attrs = \'{}\'::jsonb THEN \'{}\'::jsonb\n                                   ELSE jsonb_build_object(\'attrs\', r.attrs) END AS row_json\n                      FROM relationship r\n                      JOIN relationship_type rt ON rt.id = r.relationship_type_id\n                      JOIN entity ef ON ef.id = r.from_entity_id\n                      JOIN entity et ON et.id = r.to_entity_id\n                     WHERE rt.domain_id = v_domain AND rt.name = v_name\n                       AND ef.active AND et.active) q;\n                v_rels := v_rels || jsonb_build_object(v_name, v_rows);\n            END LOOP;\n\n            v_data := jsonb_build_object(\'labels\', v_labels)\n                      || jsonb_build_object(\'sets\', v_sets, \'parameters\', v_params,\n                                         \'parameter_defaults\', v_defaults,\n                                         \'relationships\', v_rels);\n            v_hash := encode(sha256(convert_to(v_data::text, \'UTF8\')), \'hex\');\n            SELECT id INTO v_id FROM dataset\n             WHERE problem_id = v_problem AND data_hash = v_hash;\n            IF v_id IS NULL THEN\n                INSERT INTO dataset (problem_id, data) VALUES (v_problem, v_data)\n                RETURNING id INTO v_id;\n            END IF;\n            RETURN v_id;\n        END $function$'

